ZONES = {"NL": 1, "DE": 2, "US": 3}
BASE = {1: 4.0, 2: 6.0, 3: 12.0}
PER_KG = {1: 0.5, 2: 0.8, 3: 1.5}


def shipping_cost(weight_kg, destination, express=False, insured=False):
    if weight_kg > 0:
        if destination in ZONES:
            zone = ZONES[destination]
            if weight_kg <= 30:
                cost = BASE[zone] + weight_kg * PER_KG[zone]
                if express:
                    cost *= 1.5
                    if insured:
                        cost += 10
                return round(cost, 2)
            else:
                raise ValueError("too heavy")
        else:
            raise ValueError(f"unknown destination: {destination}")
    else:
        raise ValueError("weight must be positive")
